    /**
     * Binds positional parameters (1-based) onto a prepared statement via {@link PreparedStatement#setObject}.
     * A {@code null} array is treated as "no parameters".
     */
    private static void bindParameters(@NotNull PreparedStatement dbStat, @Nullable Object[] params) throws SQLException {
        if (params != null) {
            for (int i = 0; i < params.length; i++) {
                dbStat.setObject(i + 1, params[i]);
            }
        }
    }

    public static void executeSQL(Connection session, String sql, Object... params) throws SQLException {
        try (PreparedStatement dbStat = session.prepareStatement(sql)) {
            bindParameters(dbStat, params);
            dbStat.execute();
